commands.command:
node --input-type=module - <<'JS'
import {writeFileSync} from "node:fs";
import {canonicals} from "./conformance/index.mjs";
import {curesProbe} from "./conformance/cures-probe.mjs";
const target=canonicals().find(t=>t.release==="v3" && t.persona==="P1");
const report=curesProbe(target,process.env.EHR_BIN);
if(report.exitCode!==1 || report.verdict.violation.property!=="completable") throw Error("unexpected CURES probe");
writeFileSync("conformance/results/cures-probe-check.json",JSON.stringify(report,null,2)+"\n");
console.log("Current native CURES-removal probe refused: completable");
JS
